<node TEXT="// Search the map&apos;s connected neurOS knowledge scope. One context-rich query,&#xa;// one bounded result branch — no UUIDs or implementation details in the UI.&#xa;//&#xa;// Core Freeplane imports&#xa;import org.freeplane.core.util.LogUtils&#xa;&#xa;// Standard Java/Swing imports&#xa;import java.util.List&#xa;import javax.swing.*&#xa;import javax.swing.event.*&#xa;import java.awt.*&#xa;&#xa;// neurOS bridge imports&#xa;import com.barrymac.freeplane.addons.llm.neuros.KnowledgeContext&#xa;import com.barrymac.freeplane.addons.llm.neuros.NeurosLimits&#xa;import com.barrymac.freeplane.addons.llm.neuros.KnowledgeSource&#xa;import com.barrymac.freeplane.addons.llm.neuros.NeurosClient&#xa;import com.barrymac.freeplane.addons.llm.neuros.SearchContextBuilder&#xa;import com.barrymac.freeplane.addons.llm.ui.UiHelper&#xa;&#xa;LogUtils.info(&quot;NeurosSearch script started.&quot;)&#xa;&#xa;try {&#xa;    // --- Selected node ---&#xa;    def node = c.selected&#xa;    if (node == null) {&#xa;        UiHelper.showInformationMessage(ui, &quot;Please select a node first.&quot;)&#xa;        return&#xa;    }&#xa;&#xa;    // --- Discover this map&apos;s own knowledge context from its location ---&#xa;    KnowledgeContext knowledgeContext = KnowledgeContext.discover(node.map.file)&#xa;    if (!knowledgeContext.isEnabled()) {&#xa;        UiHelper.showInformationMessage(ui, knowledgeContext.reason)&#xa;        return&#xa;    }&#xa;    NeurosLimits limits = NeurosLimits.load(node.map.storage)&#xa;    KnowledgeSource source = knowledgeContext.source&#xa;&#xa;    // --- Bounded map context (one query, never one query per neighbour) ---&#xa;    List&lt;String&gt; ancestors = []&#xa;    if (limits.ancestorLimit &gt; 0) {&#xa;        def parent = node.parent&#xa;        while (parent != null &amp;&amp; ancestors.size() &lt; limits.ancestorLimit) {&#xa;            ancestors.add(0, SearchContextBuilder.titleFragment(parent.text ?: &apos;&apos;))&#xa;            parent = parent.parent&#xa;        }&#xa;    }&#xa;    List&lt;String&gt; children = (node.children ?: [])&#xa;            .findAll { !isGeneratedResult(it) }&#xa;            .take(limits.childLimit)&#xa;            .collect { SearchContextBuilder.titleFragment(it.text ?: &apos;&apos;) }&#xa;    String note = node.note ? node.note.plain : &apos;&apos;&#xa;&#xa;    String initialQuestion = (node.text ?: &apos;&apos;).trim()&#xa;    JTextField questionField = new JTextField(initialQuestion, 42)&#xa;    JCheckBox contextBox = new JCheckBox(&apos;Include map context for greater precision&apos;,&#xa;            limits.useContext)&#xa;    JTextArea preview = new JTextArea(7, 46)&#xa;    preview.editable = false&#xa;    preview.lineWrap = true&#xa;    preview.wrapStyleWord = true&#xa;&#xa;    Closure composeQuery = { -&gt;&#xa;        if (!contextBox.selected) {&#xa;            return questionField.text.trim()&#xa;        }&#xa;        return SearchContextBuilder.build(questionField.text, ancestors, children, note,&#xa;                limits.contextOptions())&#xa;    }&#xa;    Closure refreshPreview = { -&gt;&#xa;        try {&#xa;            preview.text = composeQuery()&#xa;        } catch (Exception previewProblem) {&#xa;            preview.text = previewProblem.message&#xa;        }&#xa;    }&#xa;    questionField.document.addDocumentListener(new DocumentListener() {&#xa;        void insertUpdate(DocumentEvent e) { refreshPreview() }&#xa;        void removeUpdate(DocumentEvent e) { refreshPreview() }&#xa;        void changedUpdate(DocumentEvent e) { refreshPreview() }&#xa;    })&#xa;    contextBox.addActionListener { refreshPreview() }&#xa;    refreshPreview()&#xa;&#xa;    JPanel panel = new JPanel(new GridBagLayout())&#xa;    GridBagConstraints gbc = new GridBagConstraints()&#xa;    gbc.insets = new Insets(4, 4, 4, 4)&#xa;    gbc.anchor = GridBagConstraints.WEST&#xa;    gbc.fill = GridBagConstraints.HORIZONTAL&#xa;    gbc.gridx = 0; gbc.gridy = 0; gbc.gridwidth = 2&#xa;    panel.add(new JLabel(&apos;Question:&apos;), gbc)&#xa;    gbc.gridy = 1&#xa;    panel.add(questionField, gbc)&#xa;    gbc.gridy = 2&#xa;    panel.add(contextBox, gbc)&#xa;    gbc.gridy = 3&#xa;    panel.add(new JLabel(&apos;Exactly what will be searched:&apos;), gbc)&#xa;    gbc.gridy = 4; gbc.fill = GridBagConstraints.BOTH&#xa;    panel.add(new JScrollPane(preview), gbc)&#xa;    gbc.gridy = 5; gbc.gridwidth = 2&#xa;    panel.add(new JLabel(source.description()), gbc)&#xa;&#xa;    Object[] options = [&apos;Search&apos;, &apos;Cancel&apos;]&#xa;    int choice = JOptionPane.showOptionDialog(&#xa;            ui.currentFrame, panel, &quot;Search neurOS Knowledge&quot;,&#xa;            JOptionPane.DEFAULT_OPTION, JOptionPane.PLAIN_MESSAGE, null,&#xa;            options, options[0])&#xa;    if (choice != 0) {&#xa;        LogUtils.info(&quot;NeurosSearch cancelled by user.&quot;)&#xa;        return&#xa;    }&#xa;&#xa;    String question&#xa;    try {&#xa;        question = composeQuery()&#xa;    } catch (Exception questionProblem) {&#xa;        UiHelper.showErrorMessage(ui, questionProblem.message)&#xa;        return&#xa;    }&#xa;    if (!question?.trim()) {&#xa;        UiHelper.showInformationMessage(ui, &quot;The question is empty — nothing to search.&quot;)&#xa;        return&#xa;    }&#xa;&#xa;    // --- One search, current scope only ---&#xa;    LogUtils.info(&quot;NeurosSearch: searching current knowledge scope with a context-rich query.&quot;)&#xa;    List hits = NeurosClient.search(source, question, limits.resultsLimit)&#xa;&#xa;    if (hits.isEmpty()) {&#xa;        UiHelper.showInformationMessage(ui,&#xa;                &quot;No results for this question.\n\n&quot; +&#xa;                        &quot;(An empty answer right after connecting usually means the knowledge &quot; +&#xa;                                        &quot;source is still preparing its search index — retry in a minute.)&quot;)&#xa;        return&#xa;    }&#xa;&#xa;    // --- Attach results as a human-readable branch ---&#xa;    String branchTitle = SearchContextBuilder.titleFragment(question) ?: &apos;neurOS results&apos;&#xa;    def parentNode = node.createChild(&quot;neurOS results: ${branchTitle}&quot;)&#xa;    parentNode.tags.add(&apos;neurOS search&apos;)&#xa;    parentNode.note = &quot;Searched ${new Date()}\n&quot; +&#xa;            &quot;Question: ${question}\n&quot; +&#xa;            &quot;${source.description()}\n&quot; +&#xa;            &quot;Map context: ${contextBox.selected ? &apos;included&apos; : &apos;not included&apos;}&quot;&#xa;&#xa;    hits.each { hit -&gt;&#xa;        String title = hit.displayName?.trim() ?: &quot;Untitled ${hit.subtype ?: &apos;knowledge&apos;}&quot;&#xa;        def hitNode = parentNode.createChild(title)&#xa;        hitNode.tags.add(&apos;neurOS result&apos;)&#xa;        hitNode.note = &quot;Type: ${hit.subtype ?: &apos;unknown&apos;}\n&quot; +&#xa;                &quot;${source.description()}\n&quot; +&#xa;                &apos;Use the link on this node to open the source material.&apos;&#xa;        hitNode.link.file = source.byIdPath(hit.uuid)&#xa;    }&#xa;&#xa;    LogUtils.info(&quot;NeurosSearch: attached ${hits.size()} result(s).&quot;)&#xa;    UiHelper.showInformationMessage(ui,&#xa;            &quot;Added ${hits.size()} result(s) from the map&apos;s knowledge scope.&quot;)&#xa;&#xa;} catch (Exception e) {&#xa;    LogUtils.severe(&quot;Error in NeurosSearch script: ${e.message}&quot;, e)&#xa;    UiHelper.showErrorMessage(ui, &quot;Search neurOS Knowledge Error: ${e.message}&quot;)&#xa;}&#xa;&#xa;/** Previous search result branches must never feed back into later queries. */&#xa;boolean isGeneratedResult(def candidate) {&#xa;    def tags = candidate?.tags?.tags ?: []&#xa;    return tags.any {&#xa;        it == &apos;neuros:search&apos; || it == &apos;neuros:hit&apos; ||&#xa;                it == &apos;neurOS search&apos; || it == &apos;neurOS result&apos;&#xa;    }&#xa;}&#xa;" ID="ID_751019524" CREATED="1794936859803" MODIFIED="1794936859804"/>
</node>
<node TEXT="NeurosPushCard.groovy" FOLDED="true" ID="ID_NEUROS_PUSH" CREATED="1786920000002" MODIFIED="1786920000002">
<attribute_layout NAME_WIDTH="202.49999 pt" VALUE_WIDTH="156.75 pt"/>
<attribute NAME="menuTitleKey" VALUE="addons.${name}.neurosPushCard"/>
<attribute NAME="menuLocation" VALUE="${addonsMenu}"/>
<attribute NAME="executionMode" VALUE="on_single_node"/>
<attribute NAME="keyboardShortcut" VALUE=""/>
<attribute NAME="execute_scripts_without_asking" VALUE="true"/>
<attribute NAME="execute_scripts_without_file_restriction" VALUE="true"/>
<attribute NAME="execute_scripts_without_write_restriction" VALUE="true"/>
<attribute NAME="execute_scripts_without_exec_restriction" VALUE="false"/>
<attribute NAME="execute_scripts_without_network_restriction" VALUE="false"/>
<node TEXT="// Save a selected mind-map branch to the map&apos;s configured neurOS write&#xa;// destination as a work-graph card. The user confirms the destination first;&#xa;// identifiers and transport details stay out of the interface.&#xa;//&#xa;// Core Freeplane imports&#xa;import org.freeplane.core.util.LogUtils&#xa;&#xa;// Standard Java/Swing imports&#xa;import javax.swing.*&#xa;&#xa;// neurOS bridge imports&#xa;import com.barrymac.freeplane.addons.llm.neuros.KnowledgeContext&#xa;import com.barrymac.freeplane.addons.llm.neuros.NeurosLimits&#xa;import com.barrymac.freeplane.addons.llm.neuros.KnowledgeSource&#xa;import com.barrymac.freeplane.addons.llm.neuros.NeurosClient&#xa;import com.barrymac.freeplane.addons.llm.neuros.CardBuilder&#xa;import com.barrymac.freeplane.addons.llm.ui.UiHelper&#xa;&#xa;LogUtils.info(&quot;NeurosPushCard script started.&quot;)&#xa;&#xa;/** Recursive node → [text:, children:] data for CardBuilder. */&#xa;Map branchData(def n) {&#xa;    [&#xa;            text    : n.text ?: &apos;&apos;,&#xa;            children: (n.children ?: []).collect { branchData(it) }&#xa;    ]&#xa;}&#xa;&#xa;try {&#xa;    // --- Discover this map&apos;s knowledge context and write destination ---&#xa;    def node = c.selected&#xa;    if (node == null) {&#xa;        UiHelper.showInformationMessage(ui, &quot;Please select a node first.&quot;)&#xa;        return&#xa;    }&#xa;    KnowledgeContext knowledgeContext = KnowledgeContext.discover(node.map.file)&#xa;    if (!knowledgeContext.isEnabled()) {&#xa;        UiHelper.showInformationMessage(ui, knowledgeContext.reason)&#xa;        return&#xa;    }&#xa;    if (!knowledgeContext.canWrite()) {&#xa;        UiHelper.showInformationMessage(ui,&#xa;                &apos;neurOS knowledge is available for this map, but its location does not &apos; +&#xa;                        &apos;provide a writable workspace for saving branches.&apos;)&#xa;        return&#xa;    }&#xa;    NeurosLimits limits = NeurosLimits.load(node.map.storage)&#xa;    KnowledgeSource source = knowledgeContext.source&#xa;&#xa;    String title = (node.text ?: &apos;&apos;).split(&apos;\n&apos;)[0].trim() ?: &apos;Untitled card&apos;&#xa;    String destinationName = new File(knowledgeContext.writeDestination).name&#xa;&#xa;    // --- Confirm the exact save ---&#xa;    int confirm = JOptionPane.showConfirmDialog(ui.currentFrame,&#xa;            &quot;Save this branch to neurOS?\n\n&quot; +&#xa;                    &quot;Title: ${title}\n&quot; +&#xa;                    &quot;${source.description()}\n&quot; +&#xa;                    &quot;Destination: ${destinationName}/${limits.cardFolder}\n&quot; +&#xa;                    &quot;Children: ${(node.children ?: []).size()}&quot;,&#xa;            &apos;Save Branch to neurOS&apos;, JOptionPane.OK_CANCEL_OPTION)&#xa;    if (confirm != JOptionPane.OK_OPTION) {&#xa;        LogUtils.info(&quot;NeurosPushCard cancelled by user.&quot;)&#xa;        return&#xa;    }&#xa;&#xa;    // --- Build &amp; write ---&#xa;    String mapName = node.map?.name ?: &apos;unnamed&apos;&#xa;    String nodeId = node.id ?: &apos;unknown&apos;&#xa;    String content = CardBuilder.build(node.text ?: &apos;&apos;, branchData(node).children, mapName, nodeId)&#xa;    String uuid = (content =~ /\[\[card:([0-9a-fA-F-]+)\]\]/)[0][1]&#xa;    String fileName = CardBuilder.fileName(uuid, title)&#xa;&#xa;    File written = NeurosClient.writeCard(knowledgeContext.writeDestination,&#xa;            limits.cardFolder, fileName, content)&#xa;    LogUtils.info(&quot;NeurosPushCard: wrote a card to the configured destination.&quot;)&#xa;&#xa;    // --- Confirm using whatever availability surface the source provides ---&#xa;    Map confirmation = NeurosClient.confirmWrite(source, written, limits.writeWaitSeconds)&#xa;&#xa;    // --- Mark the source node without exposing identifiers ---&#xa;    node.tags.add(&apos;neurOS card&apos;)&#xa;    String availability = confirmation.available ?&#xa;            &apos;available in neurOS&apos; :&#xa;            &apos;waiting for the knowledge source to confirm availability&apos;&#xa;    node.note = (node.note ? node.note + &apos;\n\n&apos; : &apos;&apos;) +&#xa;            &quot;Saved to neurOS\nTitle: ${title}\n${source.description()}\nStatus: ${availability}&quot;&#xa;&#xa;    // The link carries the source location without showing an identifier.&#xa;    node.link.file = source.byIdPath(uuid)&#xa;&#xa;    if (confirmation.available) {&#xa;        UiHelper.showInformationMessage(ui,&#xa;                &quot;Saved and available in neurOS.\n\nTitle: ${title}\n${source.description()}&quot;)&#xa;    } else {&#xa;        UiHelper.showInformationMessage(ui,&#xa;                &quot;Saved to your neurOS write destination.\n\n&quot; +&#xa;                        &quot;The knowledge source has not confirmed availability yet — &quot; +&#xa;                        &apos;you can retry or open the source later.&apos;)&#xa;    }&#xa;    LogUtils.info(&quot;NeurosPushCard finished: status=${confirmation.status}.&quot;)&#xa;&#xa;} catch (Exception e) {&#xa;    LogUtils.severe(&quot;Error in NeurosPushCard script: ${e.message}&quot;, e)&#xa;    UiHelper.showErrorMessage(ui, &quot;Save to neurOS Error: ${e.message}&quot;)&#xa;}&#xa;" ID="ID_285627841" CREATED="1794936859805" MODIFIED="1794936859806"/>
</node>
</node>
